/*
 * A210762  Triangle read by rows in which row n lists the positive integers
 *          smaller than the currently largest number in Recamán's sequence
 *          A005132 after the n-th stage, but not yet present in Recamán's
 *          sequence.
 * https://oeis.org/A210762
 *
 * Offset:    2    (a(2) is the first term)
 * Keywords:  nonn, tabf, less
 * Formula:   not a simple closed form; generated by iterating Recamán's
 *            sequence and listing all positive integers less than its current
 *            maximum that are not yet present in the Recamán sequence. The
 *            sequence is flattened row-wise
 * Range:     u8 n <= 73, u16 n <= 73, u32 n <= 73, u64 n <= 73, u128 n <= 73,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stdint.h>
#include <stdlib.h>

/* Persistent storage for computed values */
static seq_t *out = NULL;          /* flattened sequence, out[n] = a(n) for n>=2 */
static size_t out_cap = 0;         /* allocated capacity of out[] */
static size_t out_len = 0;         /* next free index in out[] */

static idx_t *recam = NULL;        /* Recamán sequence values, recam[i] = a_i */
static size_t recam_cap = 0;       /* capacity of recam[] */
static size_t recam_len = 0;       /* number of Recamán terms stored */

static unsigned char *present = NULL;   /* bitmap of numbers present in Recamán */
static size_t present_cap = 0;          /* capacity of present[] */

static idx_t current_step = 0;          /* last Recamán step computed */
static idx_t max_value = 0;             /* current maximum Recamán value */
static bool initialized = false;        /* flag to run once */

/* Expand the presence bitmap if needed */
static void ensure_presence_capacity(idx_t min_cap) {
    if (min_cap < present_cap) return;
    size_t new_cap = present_cap ? present_cap << 1 : 32;
    while (new_cap <= (size_t)min_cap) new_cap <<= 1;
    unsigned char *new_present = (unsigned char *)realloc(present, new_cap);
    if (!new_present) abort();
    for (size_t i = present_cap; i < new_cap; ++i) new_present[i] = 0;
    present = new_present;
    present_cap = new_cap;
}

/* Append an element to the flattened sequence */
static void out_append(seq_t val) {
    if (out_len + 1 > out_cap) {
        size_t new_cap = out_cap ? out_cap << 1 : 64;
        seq_t *new_out = (seq_t *)realloc(out, new_cap * sizeof(seq_t));
        if (!new_out) abort();
        out = new_out;
        out_cap = new_cap;
    }
    out[out_len++] = val;          /* store value and advance */
}

/* Generate the next Recamán term with index idx (idx >= 1) */
static void recam_next(idx_t idx) {
    /* Ensure capacity for new term */
    if (recam_len >= recam_cap) {
        size_t new_cap = recam_cap ? recam_cap << 1 : 16;
        idx_t *new_rec = (idx_t *)realloc(recam, new_cap * sizeof(idx_t));
        if (!new_rec) abort();
        recam = new_rec;
        recam_cap = new_cap;
    }

    idx_t prev = recam[recam_len - 1];
    idx_t step = idx;                     /* step = idx (as per Recamán definition) */
    idx_t cand = (prev > step) ? (prev - step) : 0;
    idx_t val;
    if (cand > 0 && !(cand < present_cap && present[cand])) {
        val = cand;
    } else {
        val = prev + step;
    }

    recam[recam_len++] = val;

    ensure_presence_capacity(val + 1);
    present[val] = 1;
    if (val > max_value) max_value = val;
}

/* One‑time initialization */
static void init_once(void) {
    /* Allocate output storage */
    out_cap = 64;
    out = (seq_t *)malloc(out_cap * sizeof(seq_t));
    out[0] = 0;       /* placeholder for indices 0,1 which are unused */
    out[1] = 0;
    out_len = 2;       /* next free index is 2 */

    /* Recamán array */
    recam_cap = 16;
    recam = (idx_t *)malloc(recam_cap * sizeof(idx_t));
    recam[0] = 0;
    recam_len = 1;

    /* Presence bitmap */
    present_cap = 32;
    present = (unsigned char *)malloc(present_cap * sizeof(unsigned char));
    for (size_t i = 0; i < present_cap; ++i) present[i] = 0;
    present[0] = 1;

    /* Compute first two Recamán steps (indices 1 and 2) */
    recam_next(1);      /* a(1) = 1 */
    recam_next(2);      /* a(2) = 3 */
    current_step = 2;   /* last finished step */
    max_value = 3;      /* current maximum after step 2 */

    initialized = true;
}

/* Ensure that a(n) is available (compute rows until index reached) */
static void ensure_a_upto(idx_t n) {
    if (!initialized) init_once();

    /* Generate full rows until we have stored at least up to index n */
    while (out_len <= n) {
        /* Produce the row corresponding to the current Recamán step */
        for (idx_t k = 1; k < max_value; ++k) {
            if (k >= present_cap) {
                out_append((seq_t)k);
            } else if (!present[k]) {
                out_append((seq_t)k);
            }
        }
        /* Advance to the next Recamán step */
        recam_next(current_step + 1);
        current_step++;
    }
}

/* Main sequence function required by the framework */
seq_t a(idx_t n) {
    if (n < 2) return 0;           /* not defined below offset; safe fallback */
    ensure_a_upto(n);
    return out[n];
}
